<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Generative AI Competitive Landscape — Q1 2026</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

  :root {
    --bg: #0f1117;
    --surface: #1a1d27;
    --surface2: #22263a;
    --border: #2e3349;
    --text: #e8eaf0;
    --text-muted: #8b90a5;
    --accent: #6366f1;
    --accent-light: #818cf8;
    --chatgpt: #10a37f;
    --copilot: #0078d4;
    --gemini: #ea4335;
    --perplexity: #1e3a5f;
    --claude: #cc785c;
    --positive: #22c55e;
    --negative: #ef4444;
    --warning: #f59e0b;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Inter', system-ui, sans-serif;
