  }

  nav a:hover, nav a.active {
    color: var(--accent-light);
    border-bottom-color: var(--accent);
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px 48px;
  }

  section {
    margin-bottom: 60px;
  }

  .section-header {
    margin-bottom: 28px;
  }

  .section-number {
    font-size: 11px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 4px;
  }

  .section-title {
    font-size: 20px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 6px;
  }

  .section-desc {
    font-size: 13px;
    color: var(--text-muted);
  }

  .card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    margin-bottom: 20px;
  }

  .card-title {
    font-size: 13px;
    font-weight: 600;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 16px;
  }

  .grid-2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .grid-3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 20px;
  }

  .grid-5 {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 16px;
  }

  .app-chip {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    font-weight: 600;
    padding: 3px 10px;
    border-radius: 6px;
  }

  .app-chip.chatgpt { background: rgba(16,163,127,0.15); color: var(--chatgpt); }
  .app-chip.copilot { background: rgba(0,120,212,0.15); color: var(--copilot); }
  .app-chip.gemini { background: rgba(234,67,53,0.15); color: var(--gemini); }
