    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
  }

  .star-label {
    font-size: 11px;
    color: var(--text-muted);
    width: 20px;
    text-align: right;
    flex-shrink: 0;
  }

  .star-track {
    flex: 1;
    height: 16px;
    background: var(--surface2);
    border-radius: 4px;
    overflow: hidden;
  }

  .star-fill {
    height: 100%;
    background: linear-gradient(90deg, #f59e0b, #fbbf24);
    border-radius: 4px;
  }

  .star-pct {
    font-size: 11px;
    color: var(--text-muted);
    width: 35px;
    text-align: right;
  }

  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
  }

  th {
    text-align: left;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--text-muted);
    padding: 10px 12px;
    border-bottom: 1px solid var(--border);
    font-weight: 600;
  }

  td {
    padding: 12px 12px;
    border-bottom: 1px solid var(--border);
    color: var(--text);
  }

  tr:last-child td { border-bottom: none; }

  .trend-up { color: var(--positive); }
  .trend-down { color: var(--negative); }

  .text-positive { color: var(--positive); }
  .text-negative { color: var(--negative); }
  .text-muted { color: var(--text-muted); }
  .text-warning { color: var(--warning); }
  .text-accent { color: var(--accent-light); }

  .callout {
    background: var(--surface2);
    border: 1px solid var(--border);
    border-left: 3px solid var(--accent);
    border-radius: 6px;
    padding: 16px 20px;
    margin: 16px 0;
    font-size: 13px;
  }

  .callout.warning {
    border-left-color: var(--warning);
  }

  .callout.success {
    border-left-color: var(--positive);
  }

  .callout.danger {
    border-left-color: var(--negative);
  }

  .callout-title {
    font-weight: 600;
    margin-bottom: 4px;
    color: #fff;
  }

  .heatmap-grid {
    display: grid;
    gap: 4px;
  }

  .heatmap-cell {
    border-radius: 6px;
    padding: 12px 8px;
    text-align: center;
    font-size: 12px;
  }

  .rec-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
  }

  .rec-priority {
    display: inline-block;
