  }

  .rec-priority.p1 { background: rgba(239,68,68,0.2); color: var(--negative); }
  .rec-priority.p2 { background: rgba(245,158,11,0.2); color: var(--warning); }
  .rec-priority.p3 { background: rgba(99,102,241,0.2); color: var(--accent-light); }

  .rec-title {
    font-size: 15px;
