    gap: 6px;
    flex-wrap: wrap;
  }

  .exec-summary {
    background: linear-gradient(135deg, #1a1d27 0%, #1e2240 100%);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 32px;
  }

  .exec-item {
    display: flex;
    gap: 16px;
    padding: 16px 0;
    border-bottom: 1px solid var(--border);
  }

  .exec-item:last-child { border-bottom: none; }

  .exec-num {
