  }

  .exec-content p {
    font-size: 13px;
    color: var(--text-muted);
    line-height: 1.6;
  }

  .theme-legend {
    display: flex;
    gap: 20px;
    margin-bottom: 16px;
    flex-wrap: wrap;
  }

  .legend-item {
    display: flex;
    align-items: center;
