    height: 280px;
  }

  @media (max-width: 768px) {
    .grid-2, .grid-3, .grid-5 { grid-template-columns: 1fr; }
    .container { padding: 20px; }
    nav { padding: 0 20px; }
    .report-header { padding: 32px 20px; }
  }
</style>
</head>
<body>

<div class="report-header">
  <div class="badge">Product Strategy — Q1 2026</div>
  <h1>Generative AI Competitive Landscape</h1>
  <p class="subtitle">User Sentiment &amp; Complaint Analysis Across Top 5 AI Apps — 41,729 Mobile Reviews</p>
  <div class="stats-bar">
    <div class="stat-item">
      <div class="stat-label">Total Reviews Analyzed</div>
      <div class="stat-value">41,729</div>
      <div class="stat-sub">Balanced corpus ~8.3K per app</div>
    </div>
    <div class="stat-item">
      <div class="stat-label">Apps Covered</div>
      <div class="stat-value">5</div>
      <div class="stat-sub">ChatGPT, Copilot, Gemini, Perplexity, Claude</div>
    </div>
    <div class="stat-item">
      <div class="stat-label">Overall Avg. Rating</div>
      <div class="stat-value">3.86</div>
      <div class="stat-sub">Cross-app mean star rating</div>
    </div>
    <div class="stat-item">
      <div class="stat-label">Mismatch Rate</div>
      <div class="stat-value">11.2%</div>
      <div class="stat-sub">Sentiment–rating divergences detected</div>
    </div>
    <div class="stat-item">
      <div class="stat-label">Top Complaint Theme</div>
      <div class="stat-value" style="color:var(--warning)">Pricing</div>
      <div class="stat-sub">Varies significantly by app</div>
    </div>
  </div>
</div>

<nav>
  <a href="#executive-overview" class="active">Executive Overview</a>
  <a href="#sentiment-comparison">Sentiment Comparison</a>
  <a href="#thematic-analysis">Thematic Complaints</a>
  <a href="#divergence">Sentiment Divergence</a>
  <a href="#review-depth">Review Depth</a>
  <a href="#recommendations">Recommendations</a>
</nav>

<div class="container">

<!-- ====================== SECTION 1: EXECUTIVE OVERVIEW ====================== -->
<section id="executive-overview">
  <div class="section-header">
    <div class="section-number">01</div>
    <div class="section-title">Executive Overview</div>
    <div class="section-desc">Key findings synthesized from 41,729 user reviews across the five leading generative AI mobile applications.</div>
  </div>

  <div class="exec-summary">
    <div class="exec-item">
      <div class="exec-num">1</div>
      <div class="exec-content">
        <h3>Microsoft Copilot dominates user satisfaction — but Perplexity and Claude face the sharpest retention risks</h3>
        <p>Copilot leads with the highest average star rating (4.24) and the highest average sentiment polarity (0.487) across General-theme reviews. However, Perplexity (7.5%) and Claude (8.0%) suffer disproportionately from Pricing/Subscription complaints — and critically, Perplexity's pricing complaints carry the highest thumbs-up engagement (7.50 avg) of any complaint theme across all apps, signaling strong community consensus around this pain point.</p>
      </div>
    </div>
    <div class="exec-item">
      <div class="exec-num">2</div>
      <div class="exec-content">
        <h3>Accuracy and Bugs drive deeper dissatisfaction than pricing — but Bugs generate the most community resonance</h3>
        <p>When users complain about accuracy or bugs, they write longer reviews, give significantly lower star ratings (1–2 stars), and receive more helpful votes from other users. Bugs/Performance reviews in Perplexity average 27.5 thumbs-up — 4× the rate of general reviews. This means bug complaints are highly visible and may disproportionately influence prospective users' download decisions.</p>
      </div>
    </div>
